<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { getEmailMessage, getEmailMessages } from '@/api/adminOperationsApi'
import type { AdminEmailMessage } from '@/models/AdminEmailMessage'
import type { AdminEmailMessageDetails } from '@/models/AdminEmailMessageDetails'
import { useAdminCurrentUserStore } from '@/stores/adminCurrentUserStore'
import { formattingCulture, useLocalization } from '@opencrm/ui/i18n'
import '../adminOperationsMessages'
const currentUserStore = useAdminCurrentUserStore()
const { t } = useLocalization()
const items = ref<AdminEmailMessage[]>([]), selected = ref<AdminEmailMessageDetails | null>(null), search = ref(''), status = ref(''), error = ref(''), isDetailsLoading = ref(false)
const canManage = computed(() => currentUserStore.isSystem || currentUserStore.currentUser?.permissions.includes('Admin.Communications.Manage') === true)
onMounted(load)
async function load() { try { items.value = (await getEmailMessages(search.value, status.value)).items } catch { error.value = t('adminOperations.emailLoadError') } }
async function open(item: AdminEmailMessage) { isDetailsLoading.value = true; error.value = ''; try { selected.value = await getEmailMessage(item.id) } catch { error.value = t('adminOperations.emailDetailsLoadError') } finally { isDetailsLoading.value = false } }
function date(value: string | null) { return value ? new Intl.DateTimeFormat(formattingCulture.value, { dateStyle: 'short', timeStyle: 'short' }).format(new Date(value)) : '—' }
function statusLabel(code: string) { const key: Record<string, string> = { pending: 'pending', queued: 'queued', retrying: 'retrying', simulated: 'simulated', sent: 'sent', delivered: 'delivered', opened: 'opened', clicked: 'clicked', failed: 'failed' }; const statusKey = key[code]; return statusKey ? t(`adminOperations.${statusKey}`) : code }
</script>
<template><section class="operations-page"><h1>{{ t('adminOperations.emailHistory') }}</h1><div class="operations-toolbar"><input v-model="search" type="search" :placeholder="t('adminOperations.emailSearchPlaceholder')" @keyup.enter="load"><SearchSelect v-model="status" :options="[{ value: '', label: t('adminOperations.allStatuses') }, ...['pending','queued','retrying','simulated','sent','delivered','opened','clicked','failed'].map(value => ({ value, label: statusLabel(value) }))]" @change="load" /><button class="secondary-button" @click="load">{{ t('adminOperations.find') }}</button><RouterLink v-if="canManage" class="primary-button link-button" to="/communications/email-compose">{{ t('adminOperations.writeEmail') }}</RouterLink></div><div v-if="error" class="form-message form-message--error">{{ error }}</div><div class="table-wrap"><table class="data-table"><thead><tr><th>{{ t('adminOperations.recipient') }}</th><th>{{ t('adminOperations.subject') }}</th><th>{{ t('adminOperations.date') }}</th><th>{{ t('adminOperations.status') }}</th><th>{{ t('adminOperations.opens') }}</th><th>{{ t('adminOperations.clicks') }}</th></tr></thead><tbody><tr v-for="item in items" :key="item.id" @click="open(item)"><td>{{ item.toEmail }}</td><td>{{ item.subject }}</td><td>{{ date(item.sentAt || item.createdAt) }}</td><td>{{ statusLabel(item.lastEventCode || item.statusCode) }}</td><td>{{ item.openCount }}</td><td>{{ item.clickCount }}</td></tr></tbody></table></div><div v-if="isDetailsLoading" class="modal-backdrop"><div class="modal-card modal-card--compact">{{ t('adminOperations.loading') }}</div></div><div v-if="selected" class="modal-backdrop" @click.self="selected = null"><div class="modal-card email-details"><div class="modal-heading"><strong>{{ t('adminOperations.email', { id: selected.id }) }}</strong><button @click="selected = null">×</button></div><dl class="details-list"><dt>{{ t('adminOperations.recipient') }}</dt><dd>{{ selected.toEmail }}</dd><dt>{{ t('adminOperations.subject') }}</dt><dd>{{ selected.subject }}</dd><dt>{{ t('adminOperations.created') }}</dt><dd>{{ date(selected.createdAt) }}</dd><dt>{{ t('adminOperations.sentDate') }}</dt><dd>{{ date(selected.sentAt) }}</dd><dt>{{ t('adminOperations.status') }}</dt><dd>{{ statusLabel(selected.lastEventCode || selected.statusCode) }}</dd><dt v-if="selected.errorMessage">{{ t('adminOperations.failed') }}</dt><dd v-if="selected.errorMessage">{{ selected.errorMessage }}</dd></dl><iframe v-if="selected.htmlBody" class="email-preview" sandbox="" :title="t('adminOperations.emailContent')" :srcdoc="selected.htmlBody"></iframe><pre v-else class="email-text">{{ selected.textBody }}</pre><div class="modal-actions"><button class="secondary-button" @click="selected = null">{{ t('adminOperations.close') }}</button></div></div></div></section></template>
